def bestMinimumPerSize(nums):
    n = len(nums)
    left = [-1] * n
    right = [n] * n
    stack = []
    for i in range(n):
        while stack and nums[stack[-1]] >= nums[i]:
            right[stack.pop()] = i
        left[i] = stack[-1] if stack else -1
        stack.append(i)
    NEG = -(10 ** 18)
    ans = [NEG] * (n + 1)
    for i in range(n):
        length = right[i] - left[i] - 1
        if nums[i] > ans[length]:
            ans[length] = nums[i]
    for k in range(n - 1, 0, -1):
        if ans[k + 1] > ans[k]:
            ans[k] = ans[k + 1]
    return ans[1:]
